import os
import importlib.util

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
mask_email = target.mask_email


def test_basic_masking():
    # Spec: user@example.com becomes u***@example.com (first-letter + *** + @domain)
    assert mask_email("user@example.com") == "u***@example.com"


def test_domain_unchanged():
    # Domain must remain unchanged, including multiple dots
    result = mask_email("john.doe@example.co.uk")
    assert result == "j***@example.co.uk"
    assert result.endswith("@example.co.uk")


def test_single_letter_local():
    # First-letter + *** + @domain
    assert mask_email("a@example.com") == "a***@example.com"


def test_keeps_at_sign():
    result = mask_email("bob@test.org")
    assert result.count("@") == 1
    assert result == "b***@test.org"


def test_missing_local_raises_valueerror():
    try:
        mask_email("@example.com")
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError for missing local part")


def test_missing_domain_raises_valueerror():
    try:
        mask_email("user@")
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError for missing domain part")


def test_no_at_raises_valueerror():
    try:
        mask_email("userexample.com")
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError when no @ present")


def test_two_at_signs_raises_valueerror():
    try:
        mask_email("us@@example.com")
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError for more than one @")


def test_return_type_is_str():
    result = mask_email("user@example.com")
    assert isinstance(result, str)

