    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError for 11 digits")


def test_separators_raise():
    try:
        format_phone("123-456-7890")
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError for separators")


def test_spaces_raise():
    try:
        format_phone("123 456 7890")
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError for spaces")


def test_nonstring_raises():
    try:
        format_phone(1234567890)
    except TypeError:
        pass
    else:
        raise AssertionError("expected TypeError for non-string")


def test_non_digits_raise():
    try:
        format_phone("123456789a")
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError for non-digits")
